const crypto = require('crypto');

// Pega aquí el mismo token privado que ya usa tu nodo /whoami.
// No lo guardes en GitHub ni lo envíes al navegador.
const BOT_TOKEN = 'PEGA_AQUI_EL_TOKEN_REAL_DE_PUCELO_BOT';

function invalid(error) {
  return [{ json: { ok: false, valid: false, error } }];
}

function parseQueryString(value) {
  const fields = {};
  try {
    for (const part of String(value).split('&')) {
      const separator = part.indexOf('=');
      if (separator < 0) continue;
      const key = decodeURIComponent(part.slice(0, separator).replace(/\+/g, ' '));
      const fieldValue = decodeURIComponent(part.slice(separator + 1).replace(/\+/g, ' '));
      fields[key] = fieldValue;
    }
  } catch {
    return null;
  }
  return fields;
}

if (!BOT_TOKEN || BOT_TOKEN.startsWith('PEGA_AQUI')) {
  throw new Error('Pega el token privado de Pucelo Bot en este nodo.');
}

const input = $input.first()?.json ?? {};
let body = input.body ?? input;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch { return invalid('invalid_json'); }
}

const initData = typeof body.initData === 'string' ? body.initData.trim() : '';
const itemId = typeof body.item_id === 'string' ? body.item_id.trim() : '';
const action = typeof body.action === 'string' ? body.action.trim() : 'complete';
if (!initData) return invalid('telegram_init_data_missing');
if (!itemId || itemId.length > 120) return invalid('item_id_invalid');
if (!['complete', 'reopen'].includes(action)) return invalid('action_invalid');

const fields = parseQueryString(initData);
if (!fields) return invalid('telegram_init_data_malformed');
const receivedHash = fields.hash ?? '';
const authDate = Number(fields.auth_date);
if (!/^[a-f0-9]{64}$/i.test(receivedHash) || !Number.isInteger(authDate)) {
  return invalid('telegram_init_data_invalid');
}

const now = Math.floor(Date.now() / 1000);
if (authDate > now + 60 || now - authDate > 600) return invalid('telegram_init_data_expired');

const dataCheckString = Object.keys(fields)
  .filter((key) => key !== 'hash')
  .sort()
  .map((key) => `${key}=${fields[key]}`)
  .join('\n');
const secretKey = crypto.createHmac('sha256', 'WebAppData').update(BOT_TOKEN).digest();
const expectedHash = crypto.createHmac('sha256', secretKey).update(dataCheckString).digest('hex');
const received = Buffer.from(receivedHash, 'hex');
const expected = Buffer.from(expectedHash, 'hex');
if (received.length !== expected.length || !crypto.timingSafeEqual(received, expected)) {
  return invalid('telegram_identity_invalid');
}

let user;
try { user = JSON.parse(fields.user ?? '{}'); } catch { return invalid('telegram_user_invalid'); }
if (!user || !Number.isSafeInteger(user.id)) return invalid('telegram_user_invalid');

return [{ json: { ok: true, valid: true, item_id: itemId, action, telegram_id: String(user.id) } }];

const auth = $('Validate Telegram initData').first()?.json ?? {};
const rows = $input.all();
if (auth.valid !== true) return [{ json: auth }];

const found = rows
  .map(({ json }) => ({ json, fields: json.fields ?? json }))
  .find(({ fields }) => String(fields['item-id'] ?? '') === String(auth.item_id));
if (!found) return [{ json: { ok: false, valid: false, error: 'item_not_found' } }];

const fields = found.fields;
if (String(fields.owner_telegram_id ?? '') !== String(auth.telegram_id)) {
  return [{ json: { ok: false, valid: false, error: 'not_owner' } }];
}

const action = auth.action === 'reopen' ? 'reopen' : 'complete';
const currentStatus = String(fields.status ?? '');
if (action === 'complete' && currentStatus !== 'available') {
  return [{ json: { ok: false, valid: false, error: currentStatus === 'completed' ? 'item_already_completed' : 'item_not_available' } }];
}
if (action === 'reopen' && currentStatus !== 'completed') {
  return [{ json: { ok: false, valid: false, error: 'item_not_completed' } }];
}

const rowId = fields.Id ?? found.json.Id ?? found.json.id ?? null;
if (rowId === null || rowId === undefined || rowId === '') {
  return [{ json: { ok: false, valid: false, error: 'nocodb_row_id_missing' } }];
}

const nextStatus = action === 'reopen' ? 'available' : 'completed';
return [{ json: {
  ok: true,
  valid: true,
  Id: rowId,
  item_id: auth.item_id,
  action,
  status: nextStatus,
  completed_at: action === 'reopen' ? null : new Date().toISOString(),
  title: fields.title ?? '',
} }];

const input = $('Verify owner and item').first()?.json ?? {};
const reopened = input.action === 'reopen';
return [{ json: {
  ok: true,
  item_id: input.item_id ?? '',
  title: input.title ?? '',
  status: input.status ?? (reopened ? 'available' : 'completed'),
  completed_at: input.completed_at ?? null,
  message: reopened ? 'Publicación reactivada' : 'Marcado como entregado',
} }];
